function makeArrow(len, color, shaftR = 0.035, headR = 0.09, headL = 0.22) {
  const g = new THREE.Group();
  const mat = new THREE.MeshLambertMaterial({ color });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, len - headL, 10), mat);
  shaft.rotation.z = -Math.PI / 2;
  shaft.position.x = (len - headL) / 2;
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headL, 12), mat);
  head.rotation.z = -Math.PI / 2;
  head.position.x = len - headL / 2;
  g.add(shaft, head);
  return g;
}

