function rebuildArc(thetaRad) {
  const pts = [];
  const steps = Math.max(2, Math.ceil(Math.abs(thetaRad) / 0.08));
  for (let i = 0; i <= steps; i++) {
    const a = thetaRad * (i / steps);
    pts.push(new THREE.Vector3(0.7 * Math.cos(a), 0, -0.7 * Math.sin(a)));
  }
  const old = arcLine.geometry;
  arcLine.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  old.dispose();
}

