Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<b>Rotating coil in a uniform field</b>
<label>Coil angle θ (°)
  <input type="range" id="coilAngle" min="0" max="360" step="5" value="45">
</label>
<div id="angleVal">θ = 45°</div>
<button id="btnRotate">▶ Steady rotation</button>
<div style="display:flex;gap:4px;align-items:center;">
  View:
  <button id="vVec" class="active">Vector view</button>
  <button id="vGraph">Graph view</button>
</div>
<div id="fluxRead" style="background:#f0f4ff;border:1px solid #b9c8ee;border-radius:4px;padding:4px 6px;">
  Φ = BA·cos θ = 0.71
</div>
<hr style="width:100%;border:0;border-top:1px solid #ddd;">
<b>Demo steps</b>
<button id="step0">1 · Maximum flux (θ=0°)</button>
<button id="step1">2 · Zero flux (θ=90°)</button>
<button id="step2">3 · Geometry → graph (θ=45°)</button>
<button id="step3">4 · Steady rotation &amp; emf</button>
<div id="stepNarr" style="font-size:11px;color:#444;max-width:220px;"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ELEMENT SPEC
// coil stack   → coilGroup: 5 nested rectangular frames (4 thin boxes each), greys #c8c8c8/#a8a8a8, 2.4 (z) × 3.6 (y), offset along local x; plane contains world Y (figure z-axis), local +X = n̂
// z-axis       → solid black Lines y∈[1.8,2.7] and [-2.7,-1.8]; LineDashedMaterial segment y∈[-1.75,1.75] through coil interior
// rotation cue → arc Line radius 0.42 at y=2.25 around Y + small cone arrowhead
// x-axis       → solid Line origin→(-2.3,0,2.3) (screen lower-left); dashed continuation origin→(1.5,0,-1.5) (screen upper-right)
// B arrow      → cylinder+cone, #1a66cc, length 2.3 along world +X, fixed (appears horizontally right from the authored camera azimuth ~78°)
// n̂ arrow      → cylinder+cone, #e08000, length 1.7 along local +X inside coilGroup (rotates with coil)
// θ arc        → thin Line radius 1.05 in xz-plane, rebuilt on every angle update; enlarged vs previous attempt
// flux readout → floating HTML label + #ui readout, updated each update()
// graph view   → 2D overlay canvas in #stage, draws Φ(t)=cos and ε(t)=sin with a synced marker

const COL_GREY1 = 0xc8c8c8, COL_GREY2 = 0xa8a8a8;
const COL_B = 0x1a66cc, COL_N = 0xe08000;

/* ── Coil: stacked rectangular turns ───────────────────────────────────── */
const coilGroup = new THREE.Group();
scene.add(coilGroup);
{
  const W = 2.4, H = 3.6, t = 0.075;
  for (let i = 0; i < 5; i++) {
    const mat = new THREE.MeshLambertMaterial({ color: i % 2 ? COL_GREY2 : COL_GREY1 });
    const xOff = (i - 2) * 0.055;
    const top = new THREE.Mesh(new THREE.BoxGeometry(0.06, t, W), mat);
    top.position.set(xOff, H / 2, 0);
    const bot = top.clone(); bot.position.y = -H / 2;
    const left = new THREE.Mesh(new THREE.BoxGeometry(0.06, H, t), mat);
    left.position.set(xOff, 0, -W / 2);
    const right = left.clone(); right.position.z = W / 2;
    coilGroup.add(top, bot, left, right);
  }
  // faint interior plane so the loop reads as an area
  const area = new THREE.Mesh(
    new THREE.PlaneGeometry(2.3, 3.5),
    new THREE.MeshBasicMaterial({ color: 0xeef2f7, transparent: true, opacity: 0.35, side: THREE.DoubleSide, depthWrite: false })
  );
  area.rotation.y = Math.PI / 2;
  coilGroup.add(area);
}
registerInteractive(coilGroup, { title: 'Rotating coil', tooltip: 'Rectangular coil (several turns)', body: 'A rectangular coil of several turns rotates at steady angular speed about the vertical z-axis. Its unit normal n̂ sweeps around relative to the fixed field B, so the flux Φ = BA·cos θ through the coil rises and falls.' });

/* ── z-axis (world Y): solid outside coil, dashed through interior ─────── */
const matBlack = new THREE.LineBasicMaterial({ color: 0x000000 });
function solidLine(a, b, mat) {
  const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints([a, b]), mat || matBlack);
  scene.add(l); return l;
}
solidLine(new THREE.Vector3(0, 1.8, 0), new THREE.Vector3(0, 2.7, 0));
solidLine(new THREE.Vector3(0, -1.8, 0), new THREE.Vector3(0, -2.7, 0));
const dashMat = new THREE.LineDashedMaterial({ color: 0x000000, dashSize: 0.16, gapSize: 0.11 });
const zDash = solidLine(new THREE.Vector3(0, -1.75, 0), new THREE.Vector3(0, 1.75, 0), dashMat);
zDash.computeLineDistances();

/* ── rotation arrow around top of z-axis ───────────────────────────────── */
{
  const pts = [];
  for (let a = 0; a <= 4.4; a += 0.1) pts.push(new THREE.Vector3(0.42 * Math.cos(a), 2.25, 0.42 * Math.sin(a)));
  scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0x000000 })));
  const aEnd = 4.4;
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.15, 10),
    new THREE.MeshBasicMaterial({ color: 0x000000 }));
  cone.position.set(0.42 * Math.cos(aEnd), 2.25, 0.42 * Math.sin(aEnd));
  const tangent = new THREE.Vector3(-Math.sin(aEnd), 0, Math.cos(aEnd)).normalize();
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tangent);
  scene.add(cone);
}

/* ── x-axis: solid toward camera-left, dashed continuation ─────────────── */
solidLine(new THREE.Vector3(0, 0, 0), new THREE.Vector3(-2.3, 0, 2.3));
const xDash = solidLine(new THREE.Vector3(0, 0, 0), new THREE.Vector3(1.5, 0, -1.5), dashMat.clone());
xDash.computeLineDistances();

/* ── arrow builder (shaft + cone along +X, then oriented) ──────────────── */
function makeArrow(len, color, shaftR = 0.035, headR = 0.09, headL = 0.22) {
  const g = new THREE.Group();
  const mat = new THREE.MeshLambertMaterial({ color });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, len - headL, 10), mat);
  shaft.rotation.z = -Math.PI / 2;
  shaft.position.x = (len - headL) / 2;
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headL, 12), mat);
  head.rotation.z = -Math.PI / 2;
  head.position.x = len - headL / 2;
  g.add(shaft, head);
  return g;
}

/* B: fixed world-space field along +X (horizontal, pointing right on screen) */
const bArrow = makeArrow(2.3, COL_B, 0.045, 0.11, 0.28);
scene.add(bArrow);
registerInteractive(bArrow, { title: 'B — uniform magnetic field', tooltip: 'Uniform field B (fixed in space)', body: 'The uniform magnetic field B points horizontally to the right and stays fixed while the coil rotates about the vertical z-axis.' });

/* n̂: rides inside the coil group along local +X (the plane normal) */
const nArrow = makeArrow(1.7, COL_N, 0.045, 0.11, 0.26);
coilGroup.add(nArrow);
registerInteractive(nArrow, { title: 'n̂ — unit normal to the coil', tooltip: 'Coil normal n̂ (rotates with the coil)', body: 'n̂ is the unit vector normal to the coil plane. Flux through the coil is Φ = BA·cos θ, where θ is the angle between n̂ and B.' });

/* θ arc between B and n̂ (rebuilt on update) — enlarged radius 1.05 */
const arcMat = new THREE.LineBasicMaterial({ color: 0x333333 });
let arcLine = new THREE.Line(new THREE.BufferGeometry(), arcMat);
scene.add(arcLine);
function rebuildArc(thetaRad) {
  const pts = [];
  const steps = Math.max(2, Math.ceil(Math.abs(thetaRad) / 0.06));
  for (let i = 0; i <= steps; i++) {
    const a = thetaRad * (i / steps);
    pts.push(new THREE.Vector3(1.05 * Math.cos(a), 0, -1.05 * Math.sin(a)));
  }
  const old = arcLine.geometry;
  arcLine.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  old.dispose();
}

/* light so Lambert materials read */
scene.add(new THREE.AmbientLight(0xffffff, 0.75));
const dl = new THREE.DirectionalLight(0xffffff, 0.8);
dl.position.set(3, 5, 4);
scene.add(dl);

/* ── state + per-angle update ──────────────────────────────────────────── */
let thetaDeg = 45;          // displayed coil angle
let thetaCont = 45;         // continuous angle (graph marker)
let playing = false;
const OMEGA = 60;           // degrees per second

const fluxLbl = addLabel('Φ = BA·cosθ', new THREE.Vector3(0.4, -2.35, 0), { fontSize: '15px', color: '#1a3a8a', background: 'rgba(255,255,255,0.85)' });
const lblN = addLabel('n̂', new THREE.Vector3(1.85, 0, 0), { fontSize: '18px', bold: true, color: '#e08000' });
const lblTheta = addLabel('θ', new THREE.Vector3(1.35, 0, 0), { fontSize: '18px', bold: true });

function update(theta) {
  thetaDeg = ((theta % 360) + 360) % 360;
  const rad = THREE.MathUtils.degToRad(thetaDeg);
  coilGroup.rotation.y = rad;
  rebuildArc(rad);
  // labels that track the moving vectors
  lblN.pos.set(1.88 * Math.cos(rad), -0.08, -1.88 * Math.sin(rad));
  const half = rad / 2;
  lblTheta.pos.set(1.38 * Math.cos(half), 0.06, -1.38 * Math.sin(half));
  const flux = Math.cos(rad);
  fluxLbl.div.innerHTML = `Φ = BA·cosθ = ${flux.toFixed(2)}`;
  document.getElementById('fluxRead').textContent = `Φ = BA·cos θ = ${flux.toFixed(2)}`;
  document.getElementById('angleVal').textContent = `θ = ${Math.round(thetaDeg)}°`;
  const slider = document.getElementById('coilAngle');
  if (document.activeElement !== slider) slider.value = Math.round(thetaDeg);
}

/* ── camera (perspective) ─────────────────────────────────────────────────
 * Azimuth ~78° puts the camera nearly on the +Z axis: world +X (the B arrow)
 * projects almost horizontally to the right, and the coil's broad face (YZ
 * plane at θ=0) is seen nearly head-on so it never collapses to a sliver.
 * heightFraction 0.8 makes the assembly fill the frame. */
setCameraView({ projection: 'perspective', azimuthDeg: 78, elevationDeg: 12, rollDeg: 0, heightFraction: 0.8, distanceScale: 1.6 });
addLabel('z', new THREE.Vector3(0.14, 2.85, 0), { fontSize: '17px', bold: true });
addLabel('x', new THREE.Vector3(-2.42, 0, 2.42), { fontSize: '17px', bold: true, offset: [-8, 14] });
addLabel('B', new THREE.Vector3(2.5, 0.05, 0), { fontSize: '19px', bold: true, color: '#1a66cc' });
update(45);

/* ── graph view overlay ────────────────────────────────────────────────── */
const graphCv = document.createElement('canvas');
graphCv.style.cssText = 'position:absolute;inset:0;display:none;background:#fff;z-index:5;';
_stage.appendChild(graphCv);
let graphMode = false;

function drawGraph() {
  const w = _stage.clientWidth, h = _stage.clientHeight;
  if (!w || !h) return;
  if (graphCv.width !== w || graphCv.height !== h) { graphCv.width = w; graphCv.height = h; }
  const ctx = graphCv.getContext('2d');
  ctx.clearRect(0, 0, w, h);
  const padL = 46, padR = 18, padT = 34, padB = 40;
  const pw = w - padL - padR, ph = h - padT - padB;
  const yMid = padT + ph / 2, amp = ph * 0.36;
  const X = a => padL + (a / 720) * pw;   // a in degrees, 0..720 (two periods)

  // axes
  ctx.strokeStyle = '#000'; ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.moveTo(padL, padT - 8); ctx.lineTo(padL, padT + ph + 8); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(padL - 6, yMid); ctx.lineTo(padL + pw + 6, yMid); ctx.stroke();
  // arrowhead on t axis
  ctx.beginPath(); ctx.moveTo(padL + pw + 12, yMid); ctx.lineTo(padL + pw + 2, yMid - 4); ctx.lineTo(padL + pw + 2, yMid + 4); ctx.fill();
  ctx.fillStyle = '#000'; ctx.font = '13px sans-serif';
  ctx.fillText('t', padL + pw + 14, yMid + 4);
  ctx.fillText('0', padL - 4, yMid + 16);
  ctx.fillText('T', X(360) - 3, yMid + 16);
  ctx.fillText('2T', X(720) - 8, yMid + 16);
  ctx.fillText('+1', padL - 24, yMid - amp + 4);
  ctx.fillText('−1', padL - 24, yMid + amp + 4);
  // period ticks
  ctx.strokeStyle = '#ccc'; ctx.setLineDash([3, 4]);
  for (const a of [360, 720]) { ctx.beginPath(); ctx.moveTo(X(a), padT); ctx.lineTo(X(a), padT + ph); ctx.stroke(); }
  ctx.setLineDash([]);

  function trace(fn, color, label, ly) {
    ctx.strokeStyle = color; ctx.lineWidth = 2.2; ctx.beginPath();
    for (let a = 0; a <= 720; a += 2) {
      const y = yMid - amp * fn(THREE.MathUtils.degToRad(a));
      a === 0 ? ctx.moveTo(X(a), y) : ctx.lineTo(X(a), y);
    }
    ctx.stroke();
    ctx.fillStyle = color; ctx.font = 'bold 14px sans-serif';
    ctx.fillText(label, padL + 10, ly);
  }
  trace(a => Math.cos(a), '#1a66cc', 'Φ(t) = BA·cos(ωt)', padT + 14);
  trace(a => Math.sin(a), '#e08000', 'ε(t) = NBAω·sin(ωt)', padT + 32);

  // synced marker
  const aM = ((thetaCont % 720) + 720) % 720;
  const rad = THREE.MathUtils.degToRad(aM);
  ctx.strokeStyle = '#888'; ctx.setLineDash([4, 4]);
  ctx.beginPath(); ctx.moveTo(X(aM), padT); ctx.lineTo(X(aM), padT + ph); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = '#1a66cc';
  ctx.beginPath(); ctx.arc(X(aM), yMid - amp * Math.cos(rad), 5, 0, 7); ctx.fill();
  ctx.fillStyle = '#e08000';
  ctx.beginPath(); ctx.arc(X(aM), yMid - amp * Math.sin(rad), 5, 0, 7); ctx.fill();
  ctx.fillStyle = '#333'; ctx.font = '12px sans-serif';
  ctx.fillText(`θ = ωt = ${Math.round(((thetaCont % 360) + 360) % 360)}°`, padL + pw - 110, padT + 14);
}

function setView(graph) {
  graphMode = graph;
  graphCv.style.display = graph ? 'block' : 'none';
  document.getElementById('vVec').classList.toggle('active', !graph);
  document.getElementById('vGraph').classList.toggle('active', graph);
  if (graph) drawGraph();
}
document.getElementById('vVec').addEventListener('click', () => setView(false));
document.getElementById('vGraph').addEventListener('click', () => setView(true));

/* ── controls ──────────────────────────────────────────────────────────── */
const slider = document.getElementById('coilAngle');
slider.addEventListener('input', () => {
  playing = false;
  document.getElementById('btnRotate').textContent = '▶ Steady rotation';
  thetaCont = parseFloat(slider.value);
  update(thetaCont);
});
const btnRotate = document.getElementById('btnRotate');
function setPlaying(on) {
  playing = on;
  btnRotate.textContent = on ? '⏸ Pause rotation' : '▶ Steady rotation';
}
btnRotate.addEventListener('click', () => setPlaying(!playing));

