let lastT = performance.now();
(function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.1, (now - lastT) / 1000);
  lastT = now;
  if (playing) {
    thetaCont += OMEGA * dt;
    update(thetaCont);
  }
